column4:
SELECT CAST(COUNT(DISTINCT r.fixture_id) AS FLOAT) / NULLIF(COUNT(DISTINCT r.fixture_id), 0) * 100 AS percentage_successful_chases
FROM history2.fixtures__runs r
WHERE r.inning = 2 AND r.score > 105;

SELECT AVG(CAST(r.score AS FLOAT) * 6.0 / NULLIF(CAST(r.overs AS FLOAT), 0)) AS average_run_rate
FROM history2.fixtures__runs r
WHERE r.inning = 2 AND r.score > 77 AND r.wickets = 1;

SELECT AVG(CAST(r.score AS FLOAT) / NULLIF(CAST(r.overs AS FLOAT), 0)) AS average_run_rate
FROM history2.fixtures__runs r
WHERE r.inning = 2 AND r.score > 15 AND r.score <= 20 AND r.overs <= 5;

SELECT AVG(CAST(r.score AS FLOAT) * 6.0 / NULLIF(CAST(r.overs AS FLOAT), 0)) AS average_run_rate
FROM history2.fixtures__runs r
WHERE r.score > 13 AND r.overs <= 5 AND r.inning = 2;

SELECT 100.0 * COUNT(*) / (SELECT COUNT(*) FROM history2.fixtures__runs r WHERE r.inning = 2 AND r.score <= 13 AND r.wickets = 8) AS win_percentage
FROM history2.fixtures__runs r
WHERE r.inning = 2 AND r.score > (SELECT TOP 1 score FROM history2.fixtures__runs WHERE inning = 1 ORDER BY fixture_id DESC);
